import { ready, emit } from './events';
import { once } from '../utils/guards';

import './router';
import './observer';
import './jellyfin-hooks';

import '../modules/header';
import '../modules/sidebar/Sidebar';
import '../modules/cards';
import '../modules/home-hero';
import '../modules/media-bar';
import '../modules/dashboard';
import '../modules/settings';
import '../modules/login';

ready(() => {
    once('ptv-app', () => {
        document.documentElement.classList.add('ptv-ready');
        emit('ready');

        console.info('[PiggieTV] Runtime started');
    });
});
